/* Opens a source in a <video>: the browser's own player, hls.js, or the Matroska remuxer. Each
   engine answers the same small interface, so the controls never ask which one is running.
   hls.js and the remuxer are dynamic imports: a film that plays natively never downloads them. */

import type { HlsConfig } from 'hls.js'
import type { PictureCue } from '../../lib/remux/pictures'
import type { Source } from '../../lib/sources'
import { proxyLoader } from '../../lib/sources/hlsProxy'
import { needsProxy, proxied, rememberBlocked, streamProxy } from '../../lib/sources/proxy'
import { settingsStore } from '../../lib/store/settings'
import { hlsErrorMessage, PlaybackError } from './errors'
import { trackLabel } from './format'
import { BitmapPreview, canPreviewWithVideo, type PreviewSource, TilePreview, VideoPreview } from './preview'
import { prefs } from './session'

export interface Track {
  id: string
  label: string
  language?: string
  /** Why it can't be chosen (a DTS track in a browser that can't decode it). */
  unavailable?: string
  /** A word on how it plays, shown under its name (audio the player converts to something this browser plays). */
  note?: string
  /** Plays only by being converted, so a track in the same language that plays as it is comes first. */
  converted?: boolean
}

/** Picture subtitles a player can draw: what is on screen at a time, and the video's shape, which the subtitle canvas is laid on. */
export interface PictureSource {
  at(time: number): PictureCue | null
  video: { width: number; height: number; displayWidth?: number; displayHeight?: number } | undefined
}

/** What an engine knows about its download, in bytes a second: how fast the file is arriving, how
 *  fast it plays (its average rate; 0 when unknown), and how many requests are open. */
export interface NetStats {
  bytesPerSecond: number
  bitrate: number
  inFlight: number
}

export interface Engine {
  readonly kind: 'native' | 'hls' | 'remux'
  /** The bytes come through the stream proxy, not straight from the host. */
  readonly viaProxy?: boolean
  /** Download figures, for engines that measure them (the remuxer, hls.js); null until there are some. */
  netStats?(): NetStats | null
  /** What the stream says its video is (a codec string like "hvc1.2.4.L153.B0", and "HDR10" or
   *  "Dolby Vision"), for engines that read it. */
  videoInfo?(): { codec: string; range?: string } | undefined
  /** Where the seek preview's pictures come from, made the first time it is asked for (the scrubber
   *  asks on the first hover); null when this engine can't give any. Torn down with the engine. */
  preview?(): PreviewSource | null
  /** The stream's chapters, for engines that read them (the remuxer): where "Opening" and "Ending" begin, and what the
   *  Chapters page lists. */
  chapters?(): { title: string; start: number }[]
  /** Called when the chapters arrive, which can be after the engine is up (a list at the far end of a big file). */
  onChapters?(listener: (chapters: { title: string; start: number }[]) => void): () => void
  /** The picture subtitles (Blu-ray PGS, DVD VobSub) of the track `selectSubtitle` last chose, or null when it chose
   *  none or a text track. Drawn by PictureSubtitles.tsx. */
  pictures?(): PictureSource | null
  audio(): { tracks: Track[]; selected?: string }
  selectAudio(id: string): void | Promise<void>
  /** Subtitles inside the stream. External files are the controller's job. */
  subtitles(): Track[]
  /** Turns a stream subtitle on (cues arrive on the returned track, kept hidden: the player draws
   *  them) or all of them off with null. */
  selectSubtitle(id: string | null): Promise<TextTrack | null>
  seek(time: number): void
  /** The remuxer knows the length before the browser does; the others defer to the element. */
  duration(): number
  /** One more go after a decode error. False once that has been tried. */
  recover(): boolean
  /** What to tell the viewer if the element fails, when this engine knows more than the error code
   *  (a file Flow could only hand to the browser's own player). */
  failureMessage?: string
  /** Set when the file is playing through the browser's own player because its host blocks web
   *  pages. Flow sees none of the bytes then, so it can't pick or convert audio, and a codec the
   *  browser can't decode plays as silence. */
  readonly fallback?: 'blocked'
  /** With `fallback`, when a stream proxy was tried and couldn't open the file: why, in words for the
   *  viewer (which host refused it and what it said, or that the proxy didn't answer). */
  readonly proxyError?: string
  destroy(): void
}

export interface AttachOptions {
  startAt?: number
  signal: AbortSignal
  /** The track lists changed (a manifest parsed, an audio group switched). */
  onTracks: () => void
  onFatal: (error: PlaybackError) => void
  /** Audio that was being converted to play in this browser gave out. The picture plays on without it. */
  onAudioFailed: () => void
}

/** Text tracks the player added itself (external files, remuxed cues), so engines don't list them. */
export const ownTracks = new WeakSet<TextTrack>()

const hlsMime = 'application/vnd.apple.mpegurl'

/** Safari plays HLS itself, with AirPlay, Picture in Picture and less battery than MSE. Chrome's
 *  newer builds also answer "maybe" for HLS but lack the track APIs, so only Apple's engine counts. */
const nativeHls = (video: HTMLVideoElement) => video.canPlayType(hlsMime) !== '' && /Apple/.test(navigator.vendor)

export async function attachSource(video: HTMLVideoElement, source: Source, options: AttachOptions): Promise<Engine> {
  const engine = await open(video, source, options)
  // A server that already cut the film into preview pictures (Jellyfin's trickplay) beats decoding them here, for any engine.
  const tiles = source.trickplay
  if (tiles) {
    let preview: TilePreview | undefined
    const destroy = engine.destroy.bind(engine)
    engine.preview = () => (preview ??= new TilePreview(tiles))
    engine.destroy = () => {
      preview?.destroy()
      destroy()
    }
  }
  return engine
}

async function open(video: HTMLVideoElement, source: Source, options: AttachOptions): Promise<Engine> {
  const looksHls = /\.m3u8($|\?)/i.test(source.url)
  if (source.engine === 'remux') return attachRemux(video, source, options)
  if ((source.engine === 'hls' || looksHls) && !nativeHls(video)) return attachHls(video, source, options)
  return attachNative(video, source, options)
}

// MARK: Native

interface MediaTrackLike {
  label: string
  language: string
  enabled: boolean
}
interface MediaTrackList extends EventTarget {
  readonly length: number
  [index: number]: MediaTrackLike
}

function subtitleTracksOf(video: HTMLVideoElement): TextTrack[] {
  return Array.from(video.textTracks).filter((t) => (t.kind === 'subtitles' || t.kind === 'captions') && !ownTracks.has(t))
}

function attachNative(video: HTMLVideoElement, source: Source, { startAt, onTracks }: AttachOptions): Engine {
  const audioList = (video as HTMLVideoElement & { audioTracks?: MediaTrackList }).audioTracks
  audioList?.addEventListener('addtrack', onTracks)
  audioList?.addEventListener('change', onTracks)
  video.textTracks.addEventListener('addtrack', onTracks)
  if (startAt) video.addEventListener('loadedmetadata', () => (video.currentTime = startAt), { once: true })
  video.src = source.url

  // A second copy of the file is only worth loading for a plain file, on a device with bandwidth to spare.
  let preview: VideoPreview | null | undefined
  return {
    kind: 'native',
    preview: () => {
      if (preview === undefined) preview = source.engine === 'hls' || /\.m3u8($|\?)/i.test(source.url) || !canPreviewWithVideo() ? null : new VideoPreview(source.url)
      return preview
    },
    audio() {
      if (!audioList || audioList.length < 1) return { tracks: [] }
      const tracks: Track[] = []
      let selected: string | undefined
      for (let i = 0; i < audioList.length; i++) {
        const t = audioList[i]!
        tracks.push({ id: String(i), label: trackLabel({ name: t.label, language: t.language }), language: t.language || undefined })
        if (t.enabled) selected = String(i)
      }
      return { tracks, selected }
    },
    selectAudio(id) {
      if (!audioList) return
      for (let i = 0; i < audioList.length; i++) audioList[i]!.enabled = String(i) === id
    },
    subtitles: () => subtitleTracksOf(video).map((t, i) => ({ id: String(i), label: trackLabel({ name: t.label, language: t.language }), language: t.language || undefined })),
    async selectSubtitle(id) {
      let chosen: TextTrack | null = null
      subtitleTracksOf(video).forEach((t, i) => {
        const on = String(i) === id
        t.mode = on ? 'hidden' : 'disabled'
        if (on) chosen = t
      })
      return chosen
    },
    seek: (time) => (video.currentTime = time),
    duration: () => video.duration,
    recover: () => false,
    destroy() {
      preview?.destroy()
      audioList?.removeEventListener('addtrack', onTracks)
      audioList?.removeEventListener('change', onTracks)
      video.textTracks.removeEventListener('addtrack', onTracks)
      video.removeAttribute('src')
      video.load()
    },
  }
}

// MARK: hls.js

/** Bits per second to start from: what the last stream measured, else what the browser reports
 *  for the connection, else a broadband guess. hls.js's own default (500 kb/s) starts every
 *  stream blurry for its first seconds. */
function bandwidthEstimate(): number {
  const saved = prefs.get().bandwidth
  if (saved && saved > 0) return saved
  const downlink = (navigator as Navigator & { connection?: { downlink?: number } }).connection?.downlink
  return downlink ? downlink * 1_000_000 * 0.8 : 5_000_000
}

/** Starts downloading the engines a pick is likely to need while the viewer is still choosing, so
 *  the connecting screen doesn't wait on code: hls.js where the browser has no HLS of its own. */
export function warmEngines() {
  const probe = document.createElement('video')
  if (!probe.canPlayType(hlsMime)) void import('hls.js')
}

async function attachHls(video: HTMLVideoElement, source: Source, options: AttachOptions): Promise<Engine> {
  const { default: Hls } = await import('hls.js')
  if (options.signal.aborted) throw new DOMException('Aborted', 'AbortError')
  if (!Hls.isSupported()) {
    if (video.canPlayType(hlsMime)) return attachNative(video, source, options)
    throw new PlaybackError('This browser can’t play streams like this one. Try a current Safari, Chrome, Edge or Firefox.')
  }
  const { headers } = source
  const estimate = bandwidthEstimate()
  const config: Partial<HlsConfig> = {
    // Tuned for a fast first frame on video on demand, not for live latency.
    abrEwmaDefaultEstimate: estimate,
    capLevelToPlayerSize: true,
    maxBufferLength: 30,
    maxMaxBufferLength: 60,
    backBufferLength: 30,
    lowLatencyMode: false,
    startFragPrefetch: true,
    // CEA-608 captions would arrive as extra native tracks the player doesn't list or draw.
    enableCEA708Captions: false,
    startPosition: options.startAt ?? -1,
    xhrSetup: headers ? (xhr) => Object.entries(headers).forEach(([k, v]) => xhr.setRequestHeader(k, v)) : undefined,
  }
  // Live TV from a provider that sends no CORS headers: every request goes through the stream proxy (lib/sources/hlsProxy).
  if (source.viaProxy) config.loader = proxyLoader(Hls.DefaultConfig.loader)
  const hls = new Hls(config)
  // Subtitle cues land on hidden tracks; the player draws them in its own overlay.
  hls.subtitleDisplay = false
  let wantedSubtitle = -1
  let recovered = false

  hls.on(Hls.Events.MANIFEST_PARSED, (_, data) => {
    // The best level the estimate can carry with headroom and the screen can show. hls.js caps
    // its own choices to the player size, but not an explicit start level.
    const levels = data.levels
    const screen = (video.clientHeight || window.innerHeight) * (window.devicePixelRatio || 1) * 1.2
    let start = 0
    levels.forEach((level, i) => {
      const fits = level.bitrate <= estimate * 0.7 && (!level.height || level.height <= screen)
      if (fits && level.bitrate >= (levels[start]?.bitrate ?? 0)) start = i
    })
    hls.startLevel = start
    options.onTracks()
  })
  // hls.js turns on the stream's DEFAULT subtitle by itself; the viewer's choice (or off) wins.
  hls.on(Hls.Events.SUBTITLE_TRACKS_UPDATED, () => {
    if (hls.subtitleTrack !== wantedSubtitle) hls.subtitleTrack = wantedSubtitle
    options.onTracks()
  })
  hls.on(Hls.Events.AUDIO_TRACKS_UPDATED, options.onTracks)
  hls.on(Hls.Events.AUDIO_TRACK_SWITCHED, options.onTracks)
  hls.on(Hls.Events.ERROR, (_, data) => {
    if (!data.fatal) return
    if (data.type === Hls.ErrorTypes.MEDIA_ERROR && !recovered) {
      recovered = true
      hls.recoverMediaError()
      return
    }
    options.onFatal(new PlaybackError(hlsErrorMessage(data.type, data.details), `hls.js ${data.type}: ${data.details}`))
  })
  hls.attachMedia(video)
  hls.loadSource(source.url)

  return {
    kind: 'hls',
    audio: () => ({
      tracks: hls.audioTracks.map((t, i) => ({ id: String(i), label: trackLabel({ name: t.name, language: t.lang, channels: t.channels }), language: t.lang })),
      selected: hls.audioTrack >= 0 ? String(hls.audioTrack) : undefined,
    }),
    selectAudio: (id) => void (hls.audioTrack = Number(id)),
    subtitles: () => hls.subtitleTracks.map((t, i) => ({ id: String(i), label: trackLabel({ name: t.name, language: t.lang, forced: t.forced }), language: t.lang })),
    async selectSubtitle(id) {
      wantedSubtitle = id === null ? -1 : Number(id)
      hls.subtitleTrack = wantedSubtitle
      if (wantedSubtitle < 0) return null
      // hls.js adds the track element as it switches; give it a moment on slow devices.
      for (let i = 0; i < 30; i++) {
        const node = hls.subtitleTracks[wantedSubtitle]?.trackNode
        if (node) {
          node.track.mode = 'hidden'
          return node.track
        }
        await new Promise((r) => setTimeout(r, 100))
      }
      return null
    },
    seek: (time) => (video.currentTime = time),
    duration: () => video.duration,
    netStats() {
      // hls.js's estimate is of the whole connection, in bits a second; the level's bitrate is the stream's.
      const measured = hls.bandwidthEstimate
      if (!Number.isFinite(measured) || measured <= 0) return null
      const level = hls.levels[hls.currentLevel]
      return { bytesPerSecond: measured / 8, bitrate: (level?.bitrate ?? 0) / 8, inFlight: 0 }
    },
    recover() {
      if (recovered) return false
      recovered = true
      hls.recoverMediaError()
      return true
    },
    destroy() {
      const measured = hls.bandwidthEstimate
      if (Number.isFinite(measured) && measured > 0) prefs.set({ bandwidth: Math.round(measured) })
      hls.destroy()
      video.removeAttribute('src')
      video.load()
    },
  }
}

// MARK: Matroska

/** The browser's own player for a file whose host won't let Flow read it (most debrid download
 *  servers send no CORS headers). Chrome and Edge open Matroska themselves when they know the codecs
 *  (H.264, HEVC with hardware support, AAC, Opus, FLAC), though without a choice of audio track. */
function playBlockedFile(video: HTMLVideoElement, source: Source, options: AttachOptions, proxyError?: string): Engine {
  video.removeAttribute('src')
  video.load()
  return {
    ...attachNative(video, source, options),
    fallback: 'blocked',
    proxyError,
    failureMessage: proxyError
      ? `This file’s host doesn’t let web pages stream from it, and your stream proxy couldn’t open it: ${/[.!?]$/.test(proxyError) ? proxyError : `${proxyError}.`} Check the proxy in Settings → Playback, pick another source, or watch it in the Flow app.`
      : 'This file’s host doesn’t let web pages stream from it, and this browser can’t play the file directly. Add a stream proxy in Settings → Playback (or turn one on in AIOStreams), pick another source, or watch it in the Flow app.',
  }
}

async function attachRemux(video: HTMLVideoElement, source: Source, options: AttachOptions): Promise<Engine> {
  const { startAt, signal } = options
  const { attachMatroska, remuxSupported } = await import('../../lib/remux')
  if (!remuxSupported()) throw new PlaybackError('This browser can’t play MKV files. On iPhone, update to iOS 17.1 or later, or pick another source.')
  // Through the stream proxy a host that sends no CORS headers can be read. An add-on's request
  // headers are meant for the host, not the proxy, and the proxy forwards only Range, so a proxied
  // attempt sends none.
  // "Never Use Dolby Vision" plays a Dolby Vision file as its HDR10 picture: the remuxer leaves out its configuration.
  const hdr10Only = settingsStore.get().neverUseDolbyVision
  // Decode DTS and Dolby TrueHD off: those tracks are listed as unavailable instead of being converted.
  const convertAudio = settingsStore.get().decodeLosslessAudio !== false
  const open = (viaProxy: boolean) => attachMatroska(video, viaProxy ? proxied(source.url) : source.url, { headers: viaProxy ? undefined : source.headers, viaProxy, hdr10Only, convertAudio, startAt, signal })
  const failedWith = (error: unknown, name: string) => (error as Error).name === name

  let session
  // A host already known to need the proxy goes straight to it, so the first try isn't a wasted one.
  let viaProxy = needsProxy(source.url)
  try {
    try {
      session = await open(viaProxy)
    } catch (error) {
      if (!failedWith(error, 'BlockedError') || viaProxy) throw error
      // Remembered by the address Flow was given (the add-on's play link), not where it redirects to:
      // that is what the next source from the same add-on starts with.
      rememberBlocked(source.url)
      if (!streamProxy()) throw error
      viaProxy = true
      session = await open(true)
    }
  } catch (error) {
    if (failedWith(error, 'AbortError')) throw error
    // Not Matroska after all (the link had no telling extension, and Flow guessed): the browser's own player takes it from here.
    if (failedWith(error, 'NotMatroskaError')) return attachNative(video, source, options)
    // The proxy is only a way round a blocked host. If it was tried and the file still can't be
    // read (blocked, unreachable, refused), the browser's own player gets the original address. A
    // file the proxy did deliver but this browser can't play is a different problem, told as before.
    if (viaProxy && !failedWith(error, 'UnplayableError')) {
      // The reason is kept (the worker words it from what the proxy answered) and shown on screen, so
      // the person can read it off and tell us. The console has it too (the message holds hosts and
      // statuses only, never an address).
      const reason = (error as Error).message || 'It gave no reason.'
      console.warn(`Flow: the stream proxy couldn’t open this file. ${reason}`)
      return playBlockedFile(video, source, options, reason)
    }
    if (failedWith(error, 'BlockedError')) return playBlockedFile(video, source, options)
    const message = (error as Error).message || 'This file couldn’t be opened.'
    throw new PlaybackError(/source/i.test(message) ? message : `${message.replace(/\.?$/, '.')} Pick another source.`, 'remux')
  }
  const remux = session
  const stopWatching = remux.onAudioFailed(options.onAudioFailed)
  let unsubscribe: (() => void) | undefined
  let current: TextTrack | null = null
  let preview: BitmapPreview | undefined
  /** Set while a picture subtitle track is the one chosen; one object per choice, so the screen only re-renders on a change. */
  let picture: PictureSource | null = null

  return {
    kind: 'remux',
    viaProxy,
    // Keyframes read and decoded in the worker; none where this browser or file can't (then the scrubber shows the time alone).
    preview: () => (remux.thumbnailsSupported === false ? null : (preview ??= new BitmapPreview(remux, remux.video && remux.video.height > 0 ? remux.video.width / remux.video.height : undefined))),
    // The session measures the download itself (the reader in lib/remux); an older one has nothing to say.
    netStats: () => (remux as { netStats?: NetStats | null }).netStats ?? null,
    chapters: () => remux.chapters,
    onChapters: (listener) => remux.onChapters(listener),
    pictures: () => picture,
    videoInfo: () => (remux.video ? { codec: remux.video.codec, range: remux.video.range } : undefined),
    audio: () => ({
      tracks: remux.audioTracks.map((t) => ({
        id: String(t.id),
        label: trackLabel({ name: t.label, language: t.language }),
        language: t.language,
        unavailable: t.playable ? undefined : `${t.codec} can’t play in this browser`,
        // Surround is mixed down; a track that was stereo already is only converted.
        note: t.converted ? ((t.channels ?? 0) > 2 ? 'Converted to stereo' : 'Converted') : undefined,
        converted: t.converted || undefined,
      })),
      selected: String(remux.audioId ?? ''),
    }),
    selectAudio: (id) => remux.selectAudio(Number(id)),
    subtitles: () =>
      remux.subtitleTracks.map((t) => ({
        id: String(t.id),
        label: trackLabel({ name: t.label, language: t.language, forced: t.forced }),
        language: t.language,
        unavailable: t.kind === 'unsupported' ? 'This subtitle format isn’t supported' : undefined,
      })),
    async selectSubtitle(id) {
      unsubscribe?.()
      unsubscribe = undefined
      if (current) current.mode = 'disabled'
      current = null
      picture = null
      remux.selectPictures(null)
      if (id === null) return null
      const info = remux.subtitleTracks.find((t) => String(t.id) === id)
      if (info?.kind === 'image') {
        // Bitmaps, not text: they come from the worker decoded and are drawn on a canvas, so there is no TextTrack.
        remux.selectPictures(Number(id))
        picture = { at: (time) => remux.pictureAt(time), video: remux.video }
        return null
      }
      const track = video.addTextTrack('subtitles', info?.label ?? 'Subtitles', info?.language ?? '')
      ownTracks.add(track)
      track.mode = 'hidden'
      const seen = new Set<string>()
      unsubscribe = remux.onSubtitleCues(Number(id), (cues) => {
        for (const cue of cues) {
          // The same cues come again after a seek; keep one of each.
          const key = `${cue.start}|${cue.text}`
          if (seen.has(key)) continue
          seen.add(key)
          track.addCue(new VTTCue(cue.start, cue.end, cue.text))
        }
      })
      current = track
      return track
    },
    seek: (time) => void remux.seek(time),
    duration: () => remux.duration || video.duration,
    recover: () => false,
    destroy() {
      preview?.destroy()
      stopWatching()
      unsubscribe?.()
      if (current) current.mode = 'disabled'
      remux.destroy()
    },
  }
}
